const identifyTaskDB=[{"s":"Si la fiebre cambia lo que uno piensa, el que piensa es el cuerpo.","type":"El hombre máquina (La Mettrie, 1747)"},{"s":"Una barra de hierro, un cerebro tocado y un carácter distinto.","type":"El caso de Phineas Gage (1848)"},{"s":"El modo de producir la vida material condiciona las ideas.","type":"El prólogo de 1859 (clásico cuestionado)"},{"s":"Las ideas dominantes son las de la clase dominante.","type":"«La ideología alemana» (clásico cuestionado)"},{"s":"La base carga los dados, pero no dice qué número sale.","type":"Condicionar"},{"s":"Del bolsillo se deduce la frase, con fecha y todo.","type":"Determinar: la versión apaleada"},{"s":"La tesis se reinterpreta cada vez que falla.","type":"La inmunización (Popper, 1957)"},{"s":"Ni él ni Marx dijeron que lo económico fuera lo único.","type":"La carta de Engels a Bloch (1890)"},{"s":"Defender quitando primero lo que no se puede defender.","type":"G. A. Cohen (1978)"},{"s":"Ver dinero detrás de cada frase y darse por satisfecho.","type":"El reduccionismo de brocha gorda"}];
const classifyTaskDB=[{"w":"La Mettrie (1747)","gen":"Fuente","n":"El cuerpo explica al que piensa","g":"«El hombre máquina»","t":"Clásico sólido como documento de su tiempo"},{"w":"Marx (1859)","gen":"Fuente","n":"La base condiciona la vida intelectual","g":"Prólogo a la Contribución","t":"Clásico cuestionado, con sus críticas al lado"},{"w":"Marx y Engels","gen":"Fuente","n":"Las ideas dominantes de cada época","g":"«La ideología alemana», publicada en 1932","t":"Clásico cuestionado"},{"w":"Engels (1890)","gen":"Documento","n":"Lo económico no es el único factor","g":"Carta a Joseph Bloch, 21 de septiembre","t":"La negación del determinismo desde dentro"},{"w":"Popper (1957)","gen":"Fuente","n":"La inmunización contra la refutación","g":"«La miseria del historicismo»","t":"La crítica clásica"},{"w":"G. A. Cohen (1978)","gen":"Fuente","n":"La defensa que quita lo indefendible","g":"La teoría de la historia de Karl Marx","t":"Defensa analítica seria"},{"w":"Condicionar","gen":"Concepto","n":"La base carga los dados","g":"Se puede desmentir, y por eso sirve","t":"La versión que sigue viva"},{"w":"Determinar","gen":"Concepto","n":"La base dicta el resultado","g":"Las profecías fallaron con fechas","t":"La versión apaleada por la historia"},{"w":"El batán","gen":"Imagen","n":"El agua mueve los mazos","g":"Y no elige qué paño se pone debajo","t":"La imagen que resume la etapa"},{"w":"Brocha gorda","gen":"Error","n":"Dinero detrás de cada frase","g":"Explica todo, no prueba nada, insulta","t":"El modo de fallar de esta materia"}];
const completeTaskDB=[{"s":"La Mettrie publicó su libro en ___.","opts":["1747","1859","1932"],"ans":"1747"},{"s":"Marx escribió que la base ___.","opts":["condiciona","determina","obliga"],"ans":"condiciona"},{"s":"La versión que ___ está apaleada por la historia.","opts":["determina","condiciona","describe"],"ans":"determina"},{"s":"El agua mueve los mazos y no elige el ___.","opts":["paño","molino","río"],"ans":"paño"},{"s":"Popper llamó a ese vicio la ___.","opts":["inmunización","falsación","deducción"],"ans":"inmunización"},{"s":"La carta de Engels a Bloch es del año ___.","opts":["1890","1848","1978"],"ans":"1890"},{"s":"Cohen publicó su defensa en ___.","opts":["1978","1957","1890"],"ans":"1978"},{"s":"Ver dinero detrás de cada frase es brocha ___.","opts":["gorda","fina","seca"],"ans":"gorda"}];
const explainQuestions=[{"q":"¿Qué sostiene La Mettrie en «El hombre máquina» (1747), con qué etiqueta entra en esta casa y dónde termina lo que esta etapa puede decir?","ans":"Sostiene que si el estado del cuerpo cambia lo que uno piensa, entonces el que piensa es el cuerpo, y el alma como sustancia aparte deja de hacer falta para explicar nada. Él mismo contó que la idea le vino de una fiebre en la que notó su cabeza más lenta. La etiqueta se dice entera porque es media lección: clásico sólido como documento de su tiempo, con su fisiología superada y su gesto no; la biología de 1747 no sirve, y la pregunta que hizo la contesta hoy media neurología, con lesiones, fármacos y escáneres. El caso más citado del asunto es el de Phineas Gage, en 1848, y va con su propia etiqueta: los relatos más novelescos han sido corregidos por los historiadores, y lo que queda en pie basta. Y aquí está la frontera declarada: si con eso queda explicado lo que se siente por dentro es una pregunta abierta, con gente seria en los dos lados, y no se contesta en esta etapa sino en la 3 de esta misma ruta."},{"q":"Explica la tesis del prólogo de 1859 y por qué el verbo exacto que Marx escribió cambia todo lo que se puede afirmar con ella.","ans":"La tesis dice que el modo en que una sociedad produce su vida material condiciona su vida social, política e intelectual, y en «La ideología alemana» se completa con la fórmula de que las ideas dominantes de una época son las de su clase dominante. El verbo del texto de 1859 es condiciona, no dicta ni decide, y ahí cabe la etapa entera. Condicionar significa que la base carga los dados: hace mucho más probables unas ideas que otras y explica por qué, sin decir cuál va a salir en cada caso. Determinar significaría que de la base se deduce la idea, y esa versión, que es un endurecimiento posterior, está apaleada por la historia, porque las profecías fallaron con fechas y hay demasiadas excepciones que explicar. La consecuencia práctica es enorme: con la versión que condiciona hay que decir qué se vería si la explicación fuera falsa, y con la versión que determina no hace falta decir nada, porque cualquier resultado se acomoda después."},{"q":"¿Por qué las críticas van al lado de la tesis y no en nota al pie? Nombra las tres, con su etiqueta.","ans":"Porque una herramienta que se entrega sin sus objeciones se usa como dogma, y porque en esta materia el estatus de una fuente es parte de la fuente. Las tres. Popper, en «La miseria del historicismo» (1957), la crítica clásica: acusa a la tesis, en manos de sus defensores, de inmunizarse, es decir de reinterpretarse cada vez que falla hasta que ya nada pueda desmentirla, y una explicación que gana siempre ha dejado de explicar. Las profecías con sus fechas, que no son opinión sino hecho histórico: la revolución se esperaba en los países más industrializados y llegó en 1917 a uno de los menos industrializados de Europa. Y G. A. Cohen, en «La teoría de la historia de Karl Marx: una defensa» (1978), defensa analítica seria, que está en la lista aunque defienda, porque enseñó a sostener la parte defendible con argumentos limpios y a soltar la que no lo es. A eso se añade un documento que zanja la caricatura desde dentro: la carta de Engels a Joseph Bloch del 21 de septiembre de 1890."},{"q":"¿Qué dice exactamente la carta de Engels a Bloch de 1890, y por qué es la pieza más incómoda para las dos caricaturas?","ans":"Engels escribe, el 21 de septiembre de 1890, que ni él ni Marx afirmaron nunca que el factor económico fuera el único determinante, y añade algo que se agradece en un fundador: que si los jóvenes cargan demasiado el lado económico, la culpa es en parte de ellos dos, por haberlo subrayado tanto frente a quienes lo negaban. Es incómoda para las dos caricaturas al mismo tiempo. Para el adversario que quiere despachar la tesis como determinismo tosco, porque la negación viene firmada por uno de sus dos autores y no por un crítico externo. Y para el seguidor que usa la versión dura, porque no puede alegar que la corrección es un invento de sus enemigos. El valor de método es aún mayor: enseña que la versión útil de una idea a veces hay que ir a buscarla en las cartas y no en los eslóganes, y que las fuentes se leen enteras, con sus rectificaciones incluidas."},{"q":"Explica el reduccionismo de brocha gorda con sus tres señales, y cómo se reescribe una frase que cayó en él.","ans":"Es ver dinero detrás de cada frase y creer que con eso ya se entendió algo. Tres señales lo delatan. Uno: explica todo, y por eso ya no explica nada, porque encaja con cualquier resultado. Dos: no pide pruebas, porque la intención se supone en vez de mostrarse. Tres: salta del interés al insulto, es decir de una relación material comprobable a una acusación sobre una persona. La reescritura sigue tres pasos. Se cambia la intención por la relación: en vez de decir que alguien dice algo porque le pagan, se dice quién le paga, cuánto y qué frase le costaría dinero. Se añade la prueba: qué se vería si la explicación fuera falsa, por ejemplo qué pasaría el día que alguien dijera lo contrario en ese mismo micrófono. Y se añade lo que no se concluye: la sinceridad de nadie y la verdad o falsedad de lo que dijo, que son cosas distintas y que la auditoría no toca."},{"q":"¿Qué significa que la auditoría material no es un ácido universal, y por qué decirlo es parte del oficio?","ans":"Significa que la auditoría contesta dos preguntas y solo dos: de qué está hecho algo y qué relaciones lo sostienen. No contesta si lo que ese algo afirma es verdadero, ni si vale la pena, ni si la gente que lo sostiene es sincera. Por eso hay cosas que la sobreviven enteras y hay que decirlo en voz alta: que un colegio viva de mensualidades no vuelve falso el teorema que enseña, y que alguien cobre por su trabajo no vuelve falso lo que ese trabajo produce. Decirlo es parte del oficio por dos razones. La primera es de honradez: quien solo publica lo que el análisis derriba está eligiendo los resultados, y eso ya no es analizar. La segunda es de eficacia: el cinismo del que desmonta todo y no construye nada no es dominio de la herramienta, es su caricatura, y además deja a quien lo practica sin manera de distinguir un fraude de una institución imperfecta pero útil, que es justo la distinción para la que se aprendió todo esto."}];
let ansVisible=false;
function genTask(){sfx('click');const type=document.getElementById('tgType').value;const count=parseInt(document.getElementById('tgCount').value);ansVisible=false;const out=document.getElementById('tgOut');out.innerHTML='';if(type==='identify')genIdentifyTask(out,count);else if(type==='classify')genClassifyTask(out,count);else if(type==='complete')genCompleteTask(out,count);else if(type==='explain')genExplainTask(out,count);fin('s-tareas');}
function _instrBlock(out,title,lines){const ib=document.createElement('div');ib.className='tg-instruction-block';ib.innerHTML=`<h4>📋 ${title}</h4>`+lines.map(l=>`<p>${l}</p>`).join('');out.appendChild(ib);}
function genIdentifyTask(out,count){_instrBlock(out,'Instrucción',['Copia en tu cuaderno; subraya, colorea o encierra el concepto técnico ilustrado en cada oración. Escribe al lado de qué concepto se trata.','<strong>Ejemplo:</strong> Si la fiebre cambia lo que uno piensa, el que piensa es el cuerpo. → <span style="color:var(--jade);font-weight:700;">El hombre máquina (La Mettrie, 1747)</span>']);_pick(identifyTaskDB,Math.min(count,identifyTaskDB.length)).forEach((item,i)=>{const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.s}</strong><div style="border-bottom:1.5px solid var(--border);min-width:220px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.type}</div></div>`;out.appendChild(div);});}
function genClassifyTask(out,count){_instrBlock(out,'Instrucción',['Copia la siguiente tabla en tu cuaderno. Para cada elemento, completa su tipo, características, ámbito y función.']);const items=_pick(classifyTaskDB,Math.min(count,classifyTaskDB.length));const wrap=document.createElement('div');wrap.style.overflowX='auto';const th=(t,extra='')=>`<th style="padding:0.3rem 0.4rem;border:1px solid var(--border);font-size:0.72rem;text-align:center;${extra}">${t}</th>`;let html=`<table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:520px;"><thead><tr style="background:var(--pri-gl);">${th('Elemento','text-align:left;')}${th('Tipo')}${th('Características')}${th('Ámbito')}${th('Función')}</tr></thead><tbody>`;items.forEach(it=>{html+=`<tr><td style="padding:0.4rem 0.5rem;border:1px solid var(--border);font-weight:600;">${it.w}</td>`+Array(4).fill(`<td style="padding:0.4rem;border:1px solid var(--border);min-width:50px;"></td>`).join('')+'</tr>';});html+='</tbody></table>';wrap.innerHTML=html;out.appendChild(wrap);const ans=document.createElement('div');ans.className='tg-answer';ans.style.marginTop='0.8rem';ans.innerHTML='<strong>✅ Respuestas:</strong><br>'+items.map(it=>`<strong>${it.w}:</strong> Tipo: ${it.gen} | Características: ${it.n} | Ámbito: ${it.g} | Función: ${it.t}`).join('<br>');out.appendChild(ans);}
function genCompleteTask(out,count){_instrBlock(out,'Instrucción',['Copia y resuelve en tu cuaderno. Cada oración tiene un espacio ___. Elige y escribe la opción correcta.']);const pool=_shuffle([...completeTaskDB]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';const sent=item.s.replace('___','<span class="tg-blank" style="min-width:90px;">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</span>');div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${sent}</strong><div style="margin-top:0.4rem;font-size:0.82rem;color:var(--gray);">📝 Opciones: <strong>${item.opts.join(' | ')}</strong></div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
function genExplainTask(out,count){_instrBlock(out,'Instrucción',['Copia las siguientes preguntas en tu cuaderno y responde cada una de forma clara y argumentada.']);const pool=_shuffle([...explainQuestions]);for(let i=0;i<count;i++){const item=pool[i%pool.length];const div=document.createElement('div');div.className='tg-task';div.innerHTML=`<div class="tg-task-num">${i+1}</div><div class="tg-task-content"><strong>${item.q}</strong><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.5rem;height:1.3rem;">&nbsp;</div><div style="border-bottom:1.5px solid var(--border);min-width:200px;margin-top:0.3rem;height:1.3rem;">&nbsp;</div><div class="tg-answer">✅ ${item.ans}</div></div>`;out.appendChild(div);}}
