const evalTFBank=[{"q":"La Mettrie publicó «El hombre máquina» en 1747, y sin firmarlo.","a":true},{"q":"La etiqueta de La Mettrie dice que su fisiología sigue vigente.","a":false},{"q":"A Phineas Gage, en 1848, una barra de hierro le atravesó la cabeza y sobrevivió.","a":true},{"q":"Los relatos más novelescos del caso Gage han sido corregidos por los historiadores.","a":true},{"q":"En el prólogo de 1859, Marx escribió que la base «determina» la vida intelectual.","a":false},{"q":"«La ideología alemana» se publicó entera hasta 1932.","a":true},{"q":"Condicionar significa que la base carga los dados, no que dicte el resultado.","a":true},{"q":"La versión determinista de la tesis salió reforzada por el siglo veinte.","a":false},{"q":"La revolución llegó en 1917 a uno de los países menos industrializados de Europa.","a":true},{"q":"Popper acusó a la tesis dura de inmunizarse contra la refutación.","a":true},{"q":"Una explicación que encaja con cualquier resultado es la más potente de todas.","a":false},{"q":"En la carta a Bloch de 1890, Engels niega que lo económico sea el único factor.","a":true},{"q":"G. A. Cohen entra en esta etapa como el crítico más duro de Marx.","a":false},{"q":"La auditoría material dice de qué está hecho algo, no si lo que afirma es verdad.","a":true},{"q":"Escribir «lo dice porque le pagan» es un buen ejemplo de auditoría material.","a":false}];
const evalMCBank=[{"q":"El argumento central de «El hombre máquina» (1747) es que…","o":["a) Si el cuerpo cambia lo que se piensa, el que piensa es el cuerpo","b) Las máquinas llegarán a pensar","c) El alma gobierna la materia","d) La medicina debe separarse de la filosofía"],"a":0},{"q":"La etiqueta completa de La Mettrie en esta casa es…","o":["a) Divulgación con inflado","b) Clásico sólido como documento de su tiempo: fisiología superada, gesto no","c) Tesis discutida","d) Ciencia en disputa"],"a":1},{"q":"El caso de Phineas Gage se cita aquí porque…","o":["a) Demuestra el problema difícil de la conciencia","b) Prueba que el alma existe","c) Se le tocó el cerebro y cambió la persona","d) Confirma la tesis de Marx"],"a":2},{"q":"El verbo que Marx escribió en el prólogo de 1859 es…","o":["a) Determina","b) Impone","c) Dicta","d) Condiciona"],"a":3},{"q":"«Las ideas dominantes de una época son las de la clase dominante» está en…","o":["a) «La ideología alemana»","b) «La miseria del historicismo»","c) La carta a Bloch","d) «El hombre máquina»"],"a":0},{"q":"La diferencia práctica entre condicionar y determinar está en que la primera…","o":["a) Es más elegante","b) Dice qué se vería si la explicación fuera falsa","c) No admite excepciones","d) No necesita fuentes"],"a":1},{"q":"La versión determinista falló de manera comprobable porque…","o":["a) Nadie la entendió","b) Era demasiado corta","c) Sus profecías fallaron con fechas","d) Engels la escribió mal"],"a":2},{"q":"La inmunización, según Popper (1957), consiste en…","o":["a) Publicar bajo seudónimo","b) Buscar datos que contradigan la teoría","c) Repetir el experimento","d) Reinterpretar la tesis cada vez que falla, hasta que nada la desmienta"],"a":3},{"q":"La carta de Engels a Joseph Bloch es del…","o":["a) 21 de septiembre de 1890","b) 14 de julio de 1893","c) 5 de mayo de 1859","d) 30 de enero de 1848"],"a":0},{"q":"Lo que hace de la carta de 1890 una pieza tan incómoda es que…","o":["a) Fue escrita en la cárcel","b) La negación del determinismo viene firmada por uno de los dos autores","c) Nadie la ha leído","d) Contradice a Popper"],"a":1},{"q":"G. A. Cohen (1978) entra en la lista de esta etapa como…","o":["a) Clásico cuestionado","b) Divulgación con inflado","c) Defensa analítica seria","d) Fuente primaria"],"a":2},{"q":"La imagen del batán enseña que…","o":["a) Las máquinas son peligrosas","b) El río siempre gana","c) Los mazos deciden solos","d) El agua mueve los mazos, pero no elige el paño"],"a":3},{"q":"La prueba de una línea para cualquier explicación material es…","o":["a) ¿Qué tendría que pasar para que esto fuera falso?","b) ¿A quién beneficia?","c) ¿Quién lo dijo primero?","d) ¿Cuánto dinero hay de por medio?"],"a":0},{"q":"Las tres señales del reduccionismo de brocha gorda son…","o":["a) Es largo, es viejo y es extranjero","b) Explica todo, no pide pruebas y salta al insulto","c) Cita fuentes, usa números y admite dudas","d) Es corto, es claro y es popular"],"a":1},{"q":"Decir que la auditoría no es un ácido universal significa que…","o":["a) Solo sirve para instituciones grandes","b) Hay que repetirla cada año","c) Hay cosas que la sobreviven enteras, y decirlo es parte del oficio","d) No se puede aplicar a la propia casa"],"a":2}];
