// ===================== LÍNEA DE TIEMPO INTERACTIVA =====================
const timelineData=[{"y":"1747","icon":"⚙️","label":"La Mettrie y la fiebre","text":"<strong>«El hombre máquina»</strong>, publicado sin firma en Leiden: <strong>si el estado del cuerpo cambia lo que uno piensa, el que piensa es el cuerpo</strong>. Lo condenaron, huyó de dos países y murió en Berlín en 1751. Etiqueta: <strong>clásico sólido como documento de su tiempo</strong>, con su fisiología superada y su gesto no."},{"y":"1848","icon":"🚂","label":"Phineas Gage","text":"Una barra de hierro atraviesa la cabeza de un capataz de ferrocarril en Vermont. <strong>Sobrevive</strong>, y sus médicos describen un cambio en su carácter. Con su etiqueta puesta: <strong>los relatos más novelescos han sido corregidos por los historiadores</strong>. Lo que queda: se tocó el cerebro y cambió la persona."},{"y":"1845-1846","icon":"📚","label":"La ideología alemana","text":"Marx y Engels escriben el libro donde está la fórmula famosa: <strong>las ideas dominantes de una época son las de la clase dominante</strong>. No se publicó entero hasta <strong>1932</strong>, y ese dato importa: media discusión del siglo se hizo sin él. Etiqueta: <strong>clásico cuestionado</strong>."},{"y":"1859","icon":"🏗️","label":"El prólogo, y el verbo","text":"En el <strong>«Prólogo a la Contribución a la crítica de la economía política»</strong>, Marx escribe que el modo de producir la vida material <strong>condiciona</strong> la vida social, política e intelectual. <strong>Condiciona, no determina</strong>: la etapa entera cabe en ese verbo. Etiqueta: <strong>clásico cuestionado</strong>."},{"y":"1890","icon":"✉️","label":"La carta de Engels a Bloch","text":"El <strong>21 de septiembre</strong>, Engels escribe que ni él ni Marx afirmaron nunca que lo económico fuera el <strong>único</strong> factor, y admite que si los jóvenes cargan tanto ese lado, <strong>la culpa es en parte de ellos dos</strong>. La negación del determinismo, firmada desde dentro."},{"y":"1957","icon":"🛡️","label":"Popper y la inmunización","text":"En <strong>«La miseria del historicismo»</strong>, Popper describe el mecanismo: la tesis <strong>se reinterpreta cada vez que falla</strong> y queda a salvo de cualquier hecho. <strong>Una explicación que gana siempre ha dejado de explicar.</strong> Etiqueta: <strong>la crítica clásica</strong>."},{"y":"1978","icon":"⚖️","label":"Cohen y la defensa limpia","text":"En <strong>«La teoría de la historia de Karl Marx: una defensa»</strong>, G. A. Cohen sostiene la parte defendible con argumentos limpios y suelta la que no lo es. Etiqueta: <strong>defensa analítica seria</strong>, y está en la lista precisamente <strong>para no quedarse con la caricatura de ningún bando</strong>."}];
function initTimeline(){const track=document.getElementById('timelineTrack');if(!track)return;timelineData.forEach((d,i)=>{const b=document.createElement('button');b.className='tl-node';b.type='button';b.dataset.idx=i;b.innerHTML=`<span class="tl-dot">${d.icon}</span><span class="tl-year">${d.y}</span><span class="tl-label">${d.label}</span>`;b.onclick=()=>showTimeline(i);track.appendChild(b);});}
function showTimeline(i){const d=timelineData[i];document.querySelectorAll('.tl-node').forEach(n=>n.classList.remove('tl-active'));document.querySelector(`.tl-node[data-idx="${i}"]`).classList.add('tl-active');document.getElementById('tlInfoIcon').textContent=d.icon;document.getElementById('tlInfoText').innerHTML=`<strong>${d.y} · ${d.label}.</strong> ${d.text}`;document.getElementById('tlInfo').style.display='flex';sfx('click');}

// ===================== SIMULACIÓN: MÉTODO DE POPPER =====================
let methodRunning=false;
function startMethod(){if(methodRunning)return;methodRunning=true;sfx('click');document.getElementById('methodBtn').style.display='none';document.getElementById('methodBranch').classList.remove('show');document.getElementById('methodResult').innerHTML='';const steps=['ms1','ms2','ms3','ms4'];const arrows=['ma1','ma2','ma3'];steps.forEach(s=>document.getElementById(s).classList.remove('active','done'));arrows.forEach(a=>document.getElementById(a).classList.remove('active'));let i=0;function next(){if(i>0){document.getElementById(steps[i-1]).classList.remove('active');document.getElementById(steps[i-1]).classList.add('done');}if(i<steps.length){if(i>0)document.getElementById(arrows[i-1]).classList.add('active');document.getElementById(steps[i]).classList.add('active');sfx('ok');i++;setTimeout(next,900);}else{document.getElementById('methodBranch').classList.add('show');}}next();}
function resolveMethod(prueba){sfx(prueba?'ok':'no');document.getElementById('methodBranch').classList.remove('show');document.getElementById('ms4').classList.remove('active');document.getElementById('ms4').classList.add('done');const r=document.getElementById('methodResult');if(prueba){r.innerHTML='<div class="method-step done" style="opacity:1;"><span class="ms-num">5</span><span class="ms-icon">🎲</span><span class="ms-text"><strong>Quedó escrito el condicionamiento:</strong> «tres programas de la misma emisora coinciden en esto, y los tres los paga la misma cooperativa». Una relación que cualquiera puede ir a mirar, y ninguna intención puesta en boca de nadie.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">✅</span><span class="ms-text"><strong>Y debajo, la prueba:</strong> «se vería el día que alguien diga lo contrario en ese micrófono». Con eso la hoja se puede desmentir, y por eso se puede sostener delante de alguien. La auditoría empieza aquí, no en la sospecha.</span></div>';}else{r.innerHTML='<div class="method-step done" style="opacity:1;border-color:var(--red);background:var(--red-gl);"><span class="ms-num">5</span><span class="ms-icon">🖌️</span><span class="ms-text"><strong>Quedó escrita una brocha gorda:</strong> una intención supuesta, sin prueba, sobre una persona con nombre. Suena valiente y explica todo de un plumazo, que es justo la señal de alarma.</span></div><div class="method-arrow active" style="margin:0.4rem 0;">⬇️</div><div class="method-step done" style="opacity:1;"><span class="ms-num">6</span><span class="ms-icon">🪤</span><span class="ms-text"><strong>El costo llega en dos partes:</strong> la frase no se puede desmentir (si argumenta, es porque le pagan; si calla, también), y de camino agravia a alguien. Popper le puso nombre a ese mecanismo en 1957. Se tacha y se reescribe con la relación y su prueba.</span></div>';}methodRunning=false;document.getElementById('methodBtn').style.display='inline-flex';document.getElementById('methodBtn').textContent='🔄 Repetir simulación';sfx('fan');}

