const parteData={"maquina":{"nombre":"El hombre máquina (1747)","icon":"⚙️","estructura":{"title":"Qué es","info":"• De <strong>La Mettrie</strong>, publicado sin firma en Leiden<br>• <strong>Si el cuerpo cambia lo que se piensa, el que piensa es el cuerpo</strong><br>• Etiqueta: <strong>clásico sólido como documento de su tiempo</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• La idea le vino de una <strong>fiebre</strong>: la cabeza más lenta<br>• Un siglo después se pudo ver: <strong>Phineas Gage, 1848</strong><br>• Hoy lo confirman lesiones, fármacos y escáneres"},"enfermedades":{"title":"Dónde se cae","info":"• Citar su <strong>fisiología</strong>, que está superada, en vez de su gesto<br>• Contar el caso Gage con los adornos que los historiadores <strong>corrigieron</strong><br>• Creer que con esto queda explicado <strong>lo que se siente por dentro</strong>"},"cuidados":{"title":"En esta casa","info":"• La etiqueta se dice <strong>entera</strong>: fisiología superada, gesto no<br>• La frontera se declara: <strong>la conciencia es la etapa 3</strong><br>• Y a Angelly se le contesta: <strong>lo que pasa en el cuerpo cambia lo que piensas</strong>"}},"base":{"nombre":"La base material (1859)","icon":"🏗️","estructura":{"title":"Qué es","info":"• Del <strong>prólogo de 1859</strong>: el modo de producir la vida material <strong>condiciona</strong> las ideas<br>• Con <strong>«La ideología alemana»</strong>: las ideas dominantes son las de la clase dominante<br>• Etiqueta de las dos: <strong>clásico cuestionado</strong>"},"funcion":{"title":"Cómo se reconoce","info":"• <strong>De qué vive</strong> una institución, con números si se pueden<br>• Y la pregunta que revela lo de encima: <strong>qué frase no puede decir sin que a alguien le cueste</strong><br>• Se escribe sin adjetivos, como un inventario"},"enfermedades":{"title":"Dónde se cae","info":"• Confundir la base con <strong>una acusación</strong>: no lo es<br>• Suponer que quien habla <strong>no cree lo que dice</strong><br>• Concluir que lo que la institución afirma es <strong>falso</strong>: eso no lo dice la base"},"cuidados":{"title":"En esta casa","info":"• Se audita la institución y <strong>no se desprecia a la gente que vive dentro</strong><br>• Se empieza por la propia: <strong>de qué vive M.E.T.A.S</strong><br>• Y el favor recibido <strong>también se declara</strong>, que también es base"}},"condiciona":{"nombre":"Condicionar, no determinar","icon":"🎲","estructura":{"title":"Qué es","info":"• <strong>Condicionar:</strong> la base carga los dados<br>• <strong>Determinar:</strong> la base dicta el resultado<br>• El verbo del texto de 1859 es <strong>condiciona</strong>, y ahí cabe la etapa"},"funcion":{"title":"Cómo se reconoce","info":"• <strong>Prueba de una línea:</strong> ¿qué tendría que pasar para que fuera falso?<br>• Si hay respuesta, condiciona; si no hay, se pasó de la raya<br>• Y cuenta las excepciones en vez de llamarlas apariencia"},"enfermedades":{"title":"Dónde se cae","info":"• Deducir <strong>la frase del bolsillo</strong> y la intención de la posición<br>• Predecir el desenlace <strong>con fecha</strong>: ahí falló la versión dura<br>• Confundir <strong>saber la corriente con saber el resultado</strong>"},"cuidados":{"title":"En esta casa","info":"• La imagen que se memoriza: <strong>el agua mueve los mazos y no elige el paño</strong><br>• Toda explicación material se escribe <strong>de modo que se pueda desmentir</strong><br>• Y si no se puede, no se guarda"}},"criticas":{"nombre":"Las críticas al lado","icon":"🛡️","estructura":{"title":"Qué es","info":"• <strong>Popper (1957):</strong> la tesis dura <strong>se inmuniza</strong><br>• <strong>Las profecías:</strong> fallaron con fechas, y en 1917 al revés de lo previsto<br>• <strong>Cohen (1978):</strong> defensa analítica seria, quita lo indefendible"},"funcion":{"title":"Cómo se reconoce","info":"• Una tesis inmunizada <strong>encaja con cualquier resultado</strong><br>• Y el documento que lo zanja desde dentro: <strong>la carta de Engels a Bloch, 1890</strong><br>• Ahí Engels reparte la culpa de la exageración entre él y Marx"},"enfermedades":{"title":"Dónde se cae","info":"• Dejarlas <strong>en nota al pie</strong>, que es donde muere lo que incomoda<br>• Usar a Popper para <strong>tirar la herramienta entera</strong><br>• O usar a Cohen para <strong>salvar también lo indefendible</strong>"},"cuidados":{"title":"En esta casa","info":"• Las críticas van <strong>al lado de la tesis</strong>, en la misma página<br>• El tribunal completo a Marx <strong>vive en el Expediente Rojo</strong>, y se remite<br>• Aquí entran solo como el manual de fallos de la herramienta"}}};
let labParte='maquina',labAspecto='estructura';
function labShowParte(parteKey){labParte=parteKey;updateLabDisplay();document.querySelectorAll('.lab-cont-btn').forEach(b=>b.classList.remove('active-pri'));const btn=document.querySelector(`[data-parte="${parteKey}"]`);if(btn)btn.classList.add('active-pri');if(typeof sfx==='function')sfx('click');}
function labShowAspecto(aspectoKey){labAspecto=aspectoKey;updateLabDisplay();document.querySelectorAll('.lab-asp-btn').forEach(b=>b.classList.remove('active-sec'));const btn=document.querySelector(`[data-aspecto="${aspectoKey}"]`);if(btn)btn.classList.add('active-sec');if(typeof sfx==='function')sfx('click');}
function updateLabDisplay(){const data=parteData[labParte];const asp=data[labAspecto];document.getElementById('lab-sentence').innerHTML=`🦉 Explorando: <strong>${data.nombre}</strong> → <strong>${asp.title}</strong>`;document.getElementById('lab-display').innerHTML=`<div class="lab-cont-header">${data.icon} ${data.nombre}</div><div class="lab-asp-title">${asp.title}</div><div class="lab-asp-info">${asp.info}</div>`;}

// ===================== PREGUNTAS DE LAS LECTURAS =====================
// Tres baterías sobre los cinco textos: comprensión lectora (25, cinco por
// voz: Borges, Cervantes, Harari, Entrevista y Quintero y Gala), completar
// (10) y análisis complejo (10). Los bancos se escriben desde
// _dev/inyecta-bancos-hombre-maquina.js, como todos los demás.
const lectComprensionBank=[{"t":"Borges","q":"¿Qué encargo recibió el narrador del cuento?","o":["a) La historia de una virtud, la puntualidad, para un volumen conmemorativo","b) Catalogar una biblioteca donada","c) Traducir a La Mettrie al español","d) Escribir la biografía de Marx"],"c":0},{"t":"Borges","q":"¿Cuál fue el hallazgo que le cambió el trabajo?","o":["a) Que los antiguos elogiaban mucho la puntualidad","b) Que los moralistas antiguos no le dedican un renglón: era una virtud joven y fabricada","c) Que el encargo estaba mal pagado","d) Que la palabra no existía en latín"],"c":1},{"t":"Borges","q":"Según el cuento, ¿qué mostró E. P. Thompson en 1967?","o":["a) Que el reloj se inventó en la Edad Media","b) Que los obreros odiaban las fábricas","c) Que al pasar del trabajo por tarea al trabajo por hora, la gente cambió de moral","d) Que la puntualidad es una virtud antigua"],"c":2},{"t":"Borges","q":"¿Cuáles fueron las dos preguntas que le hizo su madre?","o":["a) Cuánto le pagaban y cuándo terminaba","b) Por qué escribía tan largo y para quién","c) Si había leído a Marx y si lo había entendido","d) Qué tendría que ocurrir para que alguna frase suya fuera falsa, y si el cariño de ella también era el crédito con otro nombre"],"c":3},{"t":"Borges","q":"¿Cómo quedó el volumen después de rehacerlo?","o":["a) Más corto y menos brillante, con el cariño sin nota y sin explicar","b) Más largo y más valiente","c) Igual que las ochenta páginas","d) Sin publicar"],"c":0},{"t":"Cervantes","q":"¿Qué recuerda Sancho al oír el golpeteo?","o":["a) La aventura de los molinos de viento","b) La noche en que ató las manos a Rocinante y al amanecer eran seis mazos de batán","c) La cueva de Montesinos","d) El pleito de la bacía"],"c":1},{"t":"Cervantes","q":"¿Qué responde don Quijote sobre el ruido que ya lo engañó una vez?","o":["a) Que hay que huir de él","b) Que hay que atacarlo de noche","c) Que hay que ir a ver de qué está hecho, que en verlo se acaba el miedo y empieza el saber","d) Que conviene rezar primero"],"c":2},{"t":"Cervantes","q":"Según don Quijote, ¿qué es lo que el agua NO hace en el batán?","o":["a) Mover la rueda","b) Alzar los mazos","c) Correr todo el año","d) Escoger qué paño se pone debajo, de qué color y para quién"],"c":3},{"t":"Cervantes","q":"¿Qué le pregunta don Quijote al «señor Mercado» que subió el precio del maíz?","o":["a) De qué está hecho, dónde vive y quién le mueve los mazos","b) Cuánto cobra por quintal","c) Si es cristiano viejo","d) Quién le dio licencia del concejo"],"c":0},{"t":"Cervantes","q":"¿Qué señal da don Quijote para conocer cuándo uno se ha pasado de la raya?","o":["a) Que el otro se enoje","b) Preguntarse qué tendría que suceder para que lo que uno dice fuese falso","c) Que la frase sea muy larga","d) Que no haya testigos"],"c":1},{"t":"Harari","q":"Según el ensayo, ¿por qué se cita el caso de Phineas Gage con una advertencia?","o":["a) Porque no está documentado","b) Porque ocurrió en Europa","c) Porque las versiones más novelescas del caso han sido corregidas por los historiadores","d) Porque Gage no sobrevivió"],"c":2},{"t":"Harari","q":"¿Cuál es la palabra del prólogo de 1859 que el ensayo manda leer con lupa?","o":["a) Producción","b) Sociedad","c) Estructura","d) Condiciona"],"c":3},{"t":"Harari","q":"¿Para qué usa el ensayo la tesis de Lynn White Jr. sobre el estribo?","o":["a) Como contraejemplo: es una tesis discutida, y sirve para distinguir condicionar de determinar","b) Como prueba definitiva del feudalismo","c) Para desmentir a Thompson","d) Para explicar la Revolución rusa"],"c":0},{"t":"Harari","q":"¿Qué falló en público y con fecha, según el ensayo?","o":["a) El experimento de Gage","b) La versión dura de la tesis: la revolución llegó en 1917 a un país poco industrializado","c) El libro de Cohen","d) La carta de Engels"],"c":1},{"t":"Harari","q":"¿Cuáles son las dos cosas difíciles que el ensayo pide al final?","o":["a) Leer a Marx entero y aprenderse las fechas","b) Escribir a los diarios y organizarse","c) No adivinarle la intención a nadie, y hacerse la misma pregunta a uno mismo","d) Dejar de oír radio y cambiar de escuela"],"c":2},{"t":"Entrevista","q":"Según la entrevista, ¿por qué publicó La Mettrie «El hombre máquina» (1747) sin poner su nombre?","o":["a) Por modestia de médico","b) Porque era la costumbre de los impresores de Leiden","c) Porque el libro era de otro","d) Porque ya le habían quemado un libro y sabía que los cuerpos arden igual"],"c":3},{"t":"Entrevista","q":"¿Qué le pasó a su «Historia natural del alma» (1745)?","o":["a) Se perdió el manuscrito en Holanda","b) Fue premiada en París","c) Fue condenada a la hoguera","d) La tradujo Boerhaave al latín"],"c":2},{"t":"Entrevista","q":"Según La Mettrie, ¿qué medía exactamente su libertad en Berlín?","o":["a) La protección del rey Federico II, ni un dedo más","b) Su sueldo de médico militar","c) El éxito de sus libros en Francia","d) La distancia que lo separaba de París"],"c":0},{"t":"Entrevista","q":"¿Con qué imagen recibe La Mettrie el verbo «condiciona» del texto de 1859 que Montero le cuenta?","o":["a) Una hoguera que todo lo quema","b) Un resorte que condiciona la hora, pero no le dice al dueño del reloj a qué cita llegar","c) Una fiebre que no baja nunca","d) Una barra de hierro que atraviesa la cabeza"],"c":1},{"t":"Entrevista","q":"¿Qué responde La Mettrie cuando Montero le pregunta por lo que se siente por dentro?","o":["a) Que la fisiología ya lo explicó completo","b) Que es un invento de los teólogos","c) Que se explica con la bilis y el insomnio","d) Que no lo sabe, y que la pregunta queda abierta para los que vengan"],"c":3},{"t":"Quintero y Gala","q":"Según Gala, ¿cómo se le han movido a él las ideas a lo largo de la vida?","o":["a) Por mudanzas de la vida, no por discusiones","b) Por argumentos bien construidos","c) Por miedo a quedarse solo","d) Por las lecturas de filosofía"],"c":0},{"t":"Quintero y Gala","q":"¿Qué imagen usa Gala para el verbo «condiciona» del prólogo de 1859?","o":["a) El reloj de una fábrica inglesa","b) Los ojos de su perro Troylo","c) Las acequias de al-Ándalus, que mandan sobre la huerta y no escriben poemas","d) Una lámpara baja en un estudio en penumbra"],"c":2},{"t":"Quintero y Gala","q":"¿Qué dato trae Quintero sobre la carta de Engels?","o":["a) Que se quemó en Berlín con los papeles de La Mettrie","b) Que Engels escribió a Bloch, el 21 de septiembre de 1890, que lo económico no era lo único","c) Que Engels se la dictó a Marx en 1859","d) Que negaba la existencia del reloj de la fábrica"],"c":1},{"t":"Quintero y Gala","q":"¿Qué dice Gala de su fundación para jóvenes creadores de Córdoba?","o":["a) Que la fundó en Madrid en 1990","b) Que allí se enseña a auditar bases materiales","c) Que decide qué escriben sus becarios","d) Que puede pagarle la pensión al talento, pero no dictarle los versos"],"c":3},{"t":"Quintero y Gala","q":"¿Con qué compara Gala una teoría que no puede perder?","o":["a) Con un batán sin agua","b) Con una acequia seca en agosto","c) Con un tahúr que juega con la baraja marcada","d) Con un giro mensual sin carta"],"c":2}];
const lectCompletarBank=[{"t":"todas","q":"La Mettrie publicó «El hombre máquina» en ___.","a":"1747"},{"t":"todas","q":"El prólogo de Marx que se cita una y otra vez en las lecturas es de ___.","a":"1859"},{"t":"Borges","q":"El trabajo de E. P. Thompson sobre el tiempo y la disciplina del trabajo es de ___.","a":"1967"},{"t":"Borges","q":"El narrador escribió ochenta páginas en ___ días y las creyó valientes.","a":"once"},{"t":"Borges","q":"La madre del narrador fue ___ durante cuarenta años.","a":"lavandera"},{"t":"Cervantes","q":"Al amanecer, lo que sonaba en la oscuridad eran seis mazos de ___.","a":"batán"},{"t":"Cervantes","q":"Sancho había atado las manos a ___ para que su amo no fuese.","a":"Rocinante"},{"t":"Harari","q":"A Phineas Gage le atravesó la cabeza una barra de hierro en ___.","a":"1848"},{"t":"Harari","q":"Lynn White Jr. publicó «Medieval Technology and Social Change» en ___.","a":"1962"},{"t":"Harari","q":"La carta de Engels a Joseph Bloch es del 21 de septiembre de ___.","a":"1890"}];
const lectAnalisisBank=[{"q":"1. Las tres primeras lecturas llegan a la misma distinción por tres puertas. Explica qué hace cada voz que las otras dos no pueden hacer, y qué se perdería leyendo solo una.","guia":"El cuento instala el error como vergüenza propia y no como advertencia ajena: el narrador descubre una llave verdadera, se emborracha con ella, escribe ochenta páginas en once días y lo desarma su madre con dos preguntas en la cocina. Eso se recuerda porque humilla un poco, y porque el lector se reconoce en el entusiasmo antes de reconocerse en la caída. El capítulo lo vuelve escena, risa y refrán, y aporta lo que los otros dos no tienen: la máquina delante, con su rueda y sus mazos, de modo que la distinción se ve en vez de explicarse, y además trae el mismo golpeteo que de noche fue gigante y de día fue mecanismo. El ensayo lo pone a escala de especie y con datos comprobables, y por eso es el único que sirve para citar en una discusión: Thompson y el reloj de la fábrica en 1967 frente al estribo discutido de Lynn White en 1962, y la carta de 1890. Quien lee solo una se queda sin la vergüenza, sin la imagen o sin la prueba."},{"q":"2. El narrador del cuento y Sancho cometen el mismo error con distinta cara. Nómbralo, señala en qué se parecen sus dos versiones y en qué se distinguen.","guia":"El error es el mismo y tiene nombre en la misión: el reduccionismo de brocha gorda, que consiste en tomar una relación material verdadera y convertirla en una explicación universal que ya no se puede desmentir. El narrador lo hace por arriba, con erudición: escribe que la honradez del comerciante es el crédito con otro nombre y que la modestia del artesano es la escasez bien peinada, y lo hace en ochenta páginas que le parecen valientes. Sancho lo hace por abajo, con refrán: sale del molino diciendo que todo lo que la gente dice lo dice por lo que cobra, y lo dice contento porque le ha salido barato. Se parecen en la estructura, que es la que importa: los dos ganan siempre, los dos ahorran el trabajo de comprobar y los dos terminan hablando de personas en vez de relaciones. Se distinguen en el tono y en el precio social: al narrador su error lo lleva a un volumen impreso, y a Sancho lo corrige don Quijote antes de que agravie a un cura. En los dos casos la corrección es la misma pregunta, la de una línea."},{"q":"3. Don Quijote dice que el agua mueve los mazos y no escoge el paño, y añade que también miente el que dice que la corriente no hace nada. Explica las dos mitades y por qué la segunda es la que casi nadie dice.","guia":"La primera mitad es la advertencia contra el determinismo: sin agua no hay golpe, así que la corriente condiciona de verdad y no de mentira, pero no decide qué paño se pone debajo, ni de qué color, ni para quién. Quien confunde las dos cosas cree que sabe el resultado cuando solo sabe la corriente. La segunda mitad es la advertencia contraria y va con una frase dura: quien dice que la corriente no hace nada miente también, y con más daño, porque ese es el que no repara el canal cuando se seca. Casi nadie la dice por dos razones. Una es de conveniencia: negar el condicionamiento deja a cada quien como único responsable de su suerte, y esa idea le sale muy barata a quien ya tiene la corriente a favor. La otra es de método: reconocer que la base condiciona obliga a mirar números, contratos y horarios, que es trabajo, mientras que negarlo se hace con una frase. La misión pide sostener las dos mitades a la vez, y por eso el caso del módulo de emprendimiento aparece con las dos correcciones."},{"q":"4. El ensayo pone a Thompson (1967) y a Lynn White (1962) uno al lado del otro. Explica para qué sirve esa pareja y qué etiqueta lleva cada uno.","guia":"Sirve para enseñar, con dos casos reales, la diferencia entre una explicación material que se puede comprobar y una que se queda en tesis discutida. Thompson mostró, con archivos, que cuando el trabajo dejó de medirse por tarea y pasó a medirse por hora aparecieron el reloj de la fábrica, las multas por retraso y, en dos generaciones, una virtud del carácter que los padres enseñaban con orgullo; ese es un condicionamiento documentado, con mecanismo visible y consecuencias que se pueden rastrear. Lynn White sostuvo que el estribo, al hacer posible el combate a caballo con lanza, explica el nacimiento del feudalismo; es elegante y sigue discutida, porque otros medievalistas la han rebatido durante décadas. Las etiquetas, entonces, son distintas y hay que decirlas: el trabajo de Thompson entra como historia documentada, y la tesis de White entra como tesis discutida. Y el ensayo lo dice explícitamente: una herramienta que solo se ilustra con sus aciertos es propaganda. Poner al lado el caso que no cerró es lo que vuelve creíble al que sí cerró."},{"q":"5. ¿Por qué el cuento termina dejando el cariño de la madre «sin nota y sin explicar»? Relaciónalo con la regla de que la auditoría no es un ácido universal.","guia":"Porque hay cosas que sobreviven enteras a la auditoría, y decirlo es parte del oficio y no una concesión sentimental. La auditoría contesta dos preguntas: de qué está hecho algo y qué relaciones lo sostienen. No contesta si lo que examina es verdadero, ni si vale la pena, ni si es sincero. El narrador había empezado a contestar las tres con la misma herramienta, y por eso su madre pudo hacerle la pregunta que lo desarmó: si el cariño con que lo crió también era el crédito con otro nombre. La respuesta correcta no es que el cariño no tenga condiciones materiales (las tiene: hubo comida, hubo horarios, hubo cansancio), sino que de esas condiciones no se sigue que el cariño sea otra cosa disfrazada. Dejarlo sin nota es la manera de escribir esa distinción. Y tiene además una consecuencia práctica: quien no sabe decir qué sobrevive termina en el cinismo, que es la caricatura adolescente de esta materia, y pierde la capacidad de distinguir un fraude de una institución imperfecta pero útil."},{"q":"6. Compara la corrección que recibe el narrador del cuento con la que recibe Sancho en el camino. ¿Cuál es más eficaz y por qué?","guia":"La del narrador es una pregunta y llega desde alguien sin autoridad académica: su madre, lavandera durante cuarenta años, le pide que diga qué tendría que ocurrir en el mundo para que alguna de sus frases resultara falsa. La de Sancho es una advertencia y llega desde su amo, con ejemplos y con una regla explícita: si dices que el ventero alaba su vino porque lo vende, dices algo que se puede mirar; si dices que el cura predica porque le pagan y lo dices sin haberlo mirado, ni has probado nada ni has entendido nada, y de camino has agraviado a un hombre. Se puede defender cualquiera de las dos como más eficaz si se argumenta. La del cuento suele ganar por una razón que conviene ver: no explica nada y por eso obliga a pensar, y además viene con un caso propio (el cariño) que el narrador no puede despachar. La de don Quijote tiene la ventaja de traer el criterio ya formulado y un ejemplo del daño causado a un tercero, que es la parte que el narrador todavía no había visto. Lo común a las dos, y es lo que hay que señalar, es que ninguna discute el contenido: las dos atacan la forma, es decir el hecho de que la explicación no se pueda desmentir."},{"q":"7. El capítulo empieza con un ruido que de noche parece gigante y de día resulta ser una máquina. Explica qué tiene que ver eso con el tema de la etapa y con la etapa anterior de esta ruta.","guia":"La escena es la conexión entre las dos etapas y por eso está elegida. En la etapa 1 la pregunta de la materia se estrenó contra el miedo: se estudia el mecanismo y el miedo pierde a su cobrador. Aquí el mismo gesto sube de escala: ir a ver de qué está hecho el ruido es exactamente lo que después se hace con el precio del maíz y con el señor Mercado, y la respuesta de don Quijote lo dice sin adornos, que en verlo se acaba el miedo y empieza el saber. Hay además una diferencia que conviene marcar y que es propia de esta etapa: el batán, una vez visto, no desaparece, sigue golpeando y sigue haciendo su trabajo. Descubrir el mecanismo de una cosa no la disuelve, la vuelve auditable. El miedo del capítulo veinte se acaba al amanecer; el precio del maíz no se acaba porque uno sepa qué bodegas lo mueven. Y esa es justamente la diferencia entre desmontar un fantasma y auditar una institución, que es el paso que esta etapa añade."},{"q":"8. El ensayo dice que la sinceridad de quien habla «no es lo contrario del condicionamiento, es el modo en que el condicionamiento funciona». Explica esa frase y da un ejemplo.","guia":"Significa que el condicionamiento material no necesita mentirosos para funcionar, y que suponer lo contrario es el error de fondo de la brocha gorda. Lo que la base hace no es obligar a nadie a decir lo que no cree: hace que unas ideas resulten más fáciles de pensar, más cómodas de sostener y más baratas de decir en voz alta, de modo que quien las sostiene llega a creerlas con toda honradez. Doña Rosa, la del guion de esta misión, es el ejemplo limpio: creía de verdad que el que no madruga es porque no quiere, y lo creía porque a ella el mundo la había premiado por madrugar; nadie la engañó, y cuando le cambiaron el turno cambió de idea sin que nadie discutiera con ella. El ejemplo puede ser cualquier otro con esas dos piezas, la sinceridad y la ventaja. La consecuencia práctica es doble y hay que decirla: no se le adivina la intención a nadie, y no se toma la sinceridad del otro como prueba de que no hay condicionamiento, porque son cosas que caben juntas."},{"q":"9. Los tres primeros textos citan a Popper y a Cohen. Explica por qué una misión que enseña la herramienta de Marx incluye a su crítico más famoso y a un defensor que le quita partes.","guia":"Porque en esta materia las críticas van al lado de la tesis y no en nota al pie, y porque las dos piezas hacen trabajos distintos que la herramienta necesita. Popper, en «La miseria del historicismo» de 1957, aporta el manual de fallos: describe la inmunización, es decir el hábito de reinterpretar la tesis cada vez que los hechos la contradicen, hasta dejarla a salvo de todo y sin decir nada. Sin esa crítica, el que aprende la herramienta la defenderá con uñas la primera vez que falle en la vida real, que es exactamente lo que hizo el narrador del cuento en once días. Cohen, en 1978, aporta lo contrario y por eso hace falta: enseña que se puede defender la parte defendible con argumentos limpios si primero se suelta la que no lo es, que es lo que hace un adulto con una herencia. Juntos evitan las dos salidas fáciles: tirar la herramienta entera porque una versión suya falló, y salvarla entera porque alguna parte sirve. Y encima está el documento que lo zanja desde dentro, la carta de Engels a Bloch de 1890."},{"q":"10. Los cinco textos llevan la etiqueta de ejercicio de estilo de la casa. Explica por qué esa etiqueta pertenece al temario de esta etapa en particular, y qué pasaría si se quitara.","guia":"Porque esta etapa enseña a preguntar de qué está hecho un texto y qué lo sostiene, y un pastiche sin declarar es un texto cuya base material está escondida: el lector cree estar recibiendo la autoridad de Borges, de Cervantes o de Harari, cuando lo que hay detrás es una casa que escribe misiones para sus hijas. Enseñar a auditar el origen de un discurso y ocultar el propio sería la contradicción más rápida posible. Hay además una razón que es exactamente el tema: la voz prestada funciona como una base material invisible, porque una tesis suena más verdadera dicha con el periodo de Cervantes, y esa ventaja no la produce el argumento sino el timbre. La etiqueta obliga a separar las dos cosas, que es la misma separación que la etapa pide entre lo que una idea afirma y lo que la sostiene. Si se quitara, pasarían dos cosas comprobables: alguien citaría a Thompson, a Popper o la carta de Engels a través de una frase que ninguno escribió, y la casa quedaría produciendo el tipo de fuente inflada que su propio compendio manda cazar."}];
const xpLect={c:new Set(),f:new Set()};

/* ---------- I. Comprensión lectora ---------- */
let lcIdx=0,lcSel=-1,lcDone=false;
function showLectC(){const cont=document.getElementById('lcQ');if(!cont)return;if(lcIdx>=lectComprensionBank.length){cont.textContent='🎉 ¡Comprensión lectora completada!';document.getElementById('lcOpts').innerHTML='';document.getElementById('lcProg').textContent='Las '+lectComprensionBank.length+' preguntas respondidas';unlockAchievement('lect_master');return;}const q=lectComprensionBank[lcIdx];document.getElementById('lcProg').textContent='Pregunta '+(lcIdx+1)+' de '+lectComprensionBank.length+' · '+q.t;cont.textContent=q.q;const opts=document.getElementById('lcOpts');opts.innerHTML='';lcSel=-1;lcDone=false;q.o.forEach((o,i)=>{const b=document.createElement('button');b.className='qz-opt';b.textContent=o;b.onclick=()=>{if(lcDone)return;opts.querySelectorAll('.qz-opt').forEach(x=>x.classList.remove('sel'));b.classList.add('sel');lcSel=i;sfx('click');};opts.appendChild(b);});}
function checkLectC(){if(lcIdx>=lectComprensionBank.length)return;if(lcSel<0)return fb('fbLC','Selecciona una respuesta.',false);lcDone=true;const opts=document.querySelectorAll('#lcOpts .qz-opt');if(lcSel===lectComprensionBank[lcIdx].c){opts[lcSel].classList.add('correct');fb('fbLC','¡Correcto! +2 XP',true);if(!xpLect.c.has(lcIdx)){xpLect.c.add(lcIdx);pts(2);}sfx('ok');}else{opts[lcSel].classList.add('wrong');opts[lectComprensionBank[lcIdx].c].classList.add('correct');fb('fbLC','Incorrecto. Vuelve al texto: la respuesta está ahí.',false);sfx('no');}setTimeout(()=>{lcIdx++;showLectC();},1700);}
function resetLectC(){sfx('click');lcIdx=0;showLectC();document.getElementById('fbLC').classList.remove('show');}

/* ---------- II. Completar ---------- */
let lfIdx=0;
function showLectF(){const cont=document.getElementById('lfQ');if(!cont)return;if(lfIdx>=lectCompletarBank.length){cont.innerHTML='🎉 ¡Las diez oraciones completadas!';document.getElementById('lfProg').textContent='Terminado';const inp=document.getElementById('lfInput');if(inp)inp.style.display='none';return;}const d=lectCompletarBank[lfIdx];document.getElementById('lfProg').textContent='Oración '+(lfIdx+1)+' de '+lectCompletarBank.length+' · '+d.t;cont.innerHTML=d.q.replace('___','<span class="blank">___</span>');const inp=document.getElementById('lfInput');if(inp){inp.style.display='';inp.value='';inp.classList.remove('eval-input-ok','eval-input-no');}}
function checkLectF(){if(lfIdx>=lectCompletarBank.length)return;const inp=document.getElementById('lfInput');const d=lectCompletarBank[lfIdx];if(!inp.value.trim())return fb('fbLF','Escribe tu respuesta.',false);const ok=isCpCorrect(inp.value,d.a);inp.classList.toggle('eval-input-ok',ok);inp.classList.toggle('eval-input-no',!ok);if(ok){fb('fbLF','¡Correcto! +2 XP',true);if(!xpLect.f.has(lfIdx)){xpLect.f.add(lfIdx);pts(2);}sfx('ok');}else{fb('fbLF','Todavía no. La respuesta esperada era: '+d.a,false);sfx('no');}setTimeout(()=>{lfIdx++;showLectF();document.getElementById('fbLF').classList.remove('show');},1900);}
function resetLectF(){sfx('click');lfIdx=0;showLectF();document.getElementById('fbLF').classList.remove('show');}

